INSERT INTO t_p88532089_it_company_website_r.prospects (company_name, inn, industry, region, source, source_url, revenue, revenue_range, employee_count, status, priority, campaign, campaign_template, subsegment, campaign_priority, enrich_status, note, created_at, updated_at)
SELECT DISTINCT ON (b.inn) trim(regexp_replace(regexp_replace(regexp_replace(regexp_replace(b.name, '^ОБЩЕСТВО С ОГРАНИЧЕННОЙ ОТВЕТСТВЕННОСТЬЮ\s*', 'ООО ', 'i'), '^(НЕПУБЛИЧНОЕ |ПУБЛИЧНОЕ )?АКЦИОНЕРНОЕ ОБЩЕСТВО\s*', 'АО ', 'i'), '"(.*)"', '«\1»'), '"', '', 'g')),
 b.inn, sg.name, COALESCE(r.n, b.region, ''), 'Масштаб: рекламодатели', 'https://mat-labs.ru/analytics/company/' || b.inn, b.revenue, round(b.revenue/1000000.0)::text || ' млн ₽', COALESCE(b.staff::text,''), 'new',
 CASE WHEN b.revenue >= 1000000000 THEN 'high' ELSE 'medium' END, 'masshtab_ads', sg.tpl, sg.code, (b.revenue/1000000)::int, 'new',
 'ОКВЭД ' || b.okved || CASE WHEN COALESCE(b.city,'') <> '' THEN ', ' || b.city ELSE '' END, NOW(), NOW()
FROM (VALUES ('leasing','Лизинг','^64\.91',30000000,'ads_finance'),('finance','Факторинг и кредиты для бизнеса','^(64\.92|64\.99|66\.1[29])',30000000,'ads_finance'),('insurance','Страхование бизнеса','^65\.',30000000,'ads_finance'),('accounting','Бухгалтерия, аудит, юристы','^69\.',30000000,'ads_services'),('it','IT и SaaS для бизнеса','^(62\.0|63\.11|58\.29)',60000000,'ads_services'),('consulting','Консалтинг','^70\.22',30000000,'ads_services'),('education','Бизнес-образование','^(85\.41|85\.42|85\.23)',20000000,'ads_services'),('hr','HR и рекрутинг','^78\.',30000000,'ads_services'),('realty','Коммерческая недвижимость','^68\.20',100000000,'ads_realty'),('events','Деловые мероприятия','^82\.30',20000000,'ads_realty'),('auto','Автодилеры и аренда авто','^(45\.11|77\.1)',100000000,'ads_realty')) sg(code, name, re, min_rev, tpl)
CROSS JOIN LATERAL (SELECT * FROM t_p88532089_it_company_website_r.biz_companies x WHERE x.okved ~ sg.re AND x.revenue >= sg.min_rev AND COALESCE(x.staff,0) >= 3 ORDER BY x.revenue DESC LIMIT 200) b
